<template><section class="admin-panel"><header class="admin-section-head"><div><p>SECURITY AUDIT</p><h1>审计记录</h1></div><button type="button" @click="$emit('retry')">刷新</button></header><p class="admin-note">日志只展示脱敏元数据，不返回 IP、User-Agent 哈希、密码、令牌或邀请码原文。</p><AdminState :loading="loading" :error="error" @retry="$emit('retry')"/><div v-if="!loading&&!error" class="admin-list audit-list"><article v-for="item in page.items" :key="item.id"><div><strong>{{ item.actionCode }} · {{ item.result }}</strong><span>{{ item.createdAt }} · 管理员 #{{ item.actorUserId||'-' }} · {{ item.targetType }} #{{ item.targetId }}</span><small v-if="item.reason">原因：{{ item.reason }}</small></div><span v-if="item.errorCode" class="metric-status unavailable">{{ item.errorCode }}</span></article><p v-if="!page.items.length" class="admin-empty">暂无审计记录。</p></div><footer class="admin-pagination"><button type="button" :disabled="page.page<=1" @click="$emit('page',page.page-1)">上一页</button><span>第 {{ page.page }} 页 · 共 {{ page.total }} 条</span><button type="button" :disabled="page.page*page.size>=page.total" @click="$emit('page',page.page+1)">下一页</button></footer></section></template>
<script setup lang="ts">import type{AuditPage}from"../../services/admin";import AdminState from"./AdminState.vue";defineProps<{page:AuditPage;loading:boolean;error?:string}>();defineEmits<{retry:[];page:[page:number]}>();</script>
